styl:
u + .body .gmail-blend-screen.b-iq-utility-17 {  background: #000;
  mix-blend-mode: screen;  }
.b-iq-utility-17 u + .body .gmail-blend-diff {  background: #000;
  mix-blend-mode: difference;  }
.b-iq-utility-17 .w280 {  width: 100%;
  max-width: 280px;  }
@media screen and (max-width: 600px) {
  .b-iq-utility-17 .w280 {  max-width: 100% !important;  }
}
.b-iq-utility-17 .butt-link {  font-size: 18px;
  line-height: 27px;
  font-weight: 700;
  text-transform: none;
  text-decoration: none;
  color: #f9f9f9;
  display: block;
  padding: 16px 0 16px;
  text-align: center;
  letter-spacing: 0px;  }
.b-iq-utility-17 .white-title {  font-family: Helvetica !important;
  font-weight: 700;
